{"id":"e38217be-1f93-4402-8f19-30883992d786","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"es","slug":"papa-rellena-colombiana","public_path":"/papa-rellena-colombiana","source_url":null,"title":"Papa rellena colombiana","excerpt":"Papa rellena colombiana: bolas de res desmechada, papa, arroz y arvejas, bañadas en un rebozado de harina y fritas hasta quedar doradas. Para 6 porciones.","summary":"La papa rellena colombiana, también llamada pastel de papa, se hace mezclando carne de res desmechada, papa, arroz y arvejas con un hogao de tomate y cebolla, como el relleno de una empanada. Con esa mezcla se forman bolas compactas, se bañan en un rebozado de harina y agua, y se fríen hasta que quedan doradas por fuera.\n\nLleva 30 minutos de preparación, unas 2 horas y 10 minutos de cocción y 50 minutos de enfriado y reposo. Rinde 6 porciones de una papa rellena.","category":"Entrantes y aperitivos","difficulty":"Media","course":"Entrante","cuisine":"Colombiana","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["papa rellena colombiana","receta de papa rellena","pastel de papa colombiano","cómo hacer papas rellenas","papa rellena de carne desmechada","papa rellena con arroz y arvejas","comida colombiana"],"ingredients":[{"name":"carne de res (falda o pecho)","amount":"500","unit":"g","group":"Para la carne"},{"name":"agua","amount":"1500","unit":"ml","group":"Para la carne"},{"name":"ajo","amount":"2","unit":"","group":"Para la carne"},{"name":"papa blanca","amount":"500","unit":"g","group":"Para el relleno"},{"name":"arroz blanco cocido","amount":"300","unit":"g","group":"Para el relleno"},{"name":"arvejas","amount":"100","unit":"g","group":"Para el relleno"},{"name":"tomates","amount":"2","unit":"","group":"Para el relleno"},{"name":"cebolla larga","amount":"5","unit":"","group":"Para el relleno"},{"name":"cilantro","amount":"2","unit":"cucharada","group":"Para el relleno"},{"name":"aceite vegetal","amount":"2","unit":"cucharada","group":"Para el relleno"},{"name":"comino molido","amount":"1/2","unit":"cucharadita","group":"Para el relleno"},{"name":"harina de trigo","amount":"150","unit":"g","group":"Para el rebozado"},{"name":"huevo grande","amount":"1","unit":"","group":"Para el rebozado"},{"name":"agua fría","amount":"200","unit":"ml","group":"Para el rebozado"},{"name":"azúcar","amount":"1/2","unit":"cucharadita","group":"Para el rebozado"},{"name":"aceite vegetal para freír","amount":"1000","unit":"ml","group":"Para freír y sazonar"},{"name":"sal","amount":"2","unit":"cucharadita","group":"Para freír y sazonar"}],"steps":[{"title":"Cuece la carne","content":"Pon 500 g de carne de res en una olla con 1,5 litros de agua, 2 tallos de cebolla larga, 2 dientes de ajo y 1 cucharadita de sal. Cuando hierva, baja el fuego, tapa y cocina 1 hora y 30 minutos, hasta que la carne se deshaga con un tenedor.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Papa rellena colombiana: Cuece la carne"},{"title":"Desmecha la carne","content":"Saca la carne del caldo, déjala templar 10 minutos y desmécha con dos tenedores en hebras finas. Reserva 150 ml del caldo.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Papa rellena colombiana: Desmecha la carne"},{"title":"Prepara el guiso","content":"En una sartén honda, sofríe 3 tallos de cebolla larga y 2 tomates picados en 2 cucharadas de aceite con ½ cucharadita de sal y ½ cucharadita de comino durante 5 minutos. Añade 500 g de papa en cubos de 1 cm y los 150 ml de caldo, tapa y cocina a fuego medio-bajo 12 minutos, hasta que la papa esté tierna pero entera. Incorpora 300 g de arroz cocido, 100 g de arvejas, la carne y 2 cucharadas de cilantro picado y mezcla 5 minutos, hasta que se seque el líquido.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Papa rellena colombiana: Prepara el guiso"},{"title":"Enfría la mezcla","content":"Pasa el guiso a un bol y déjalo enfriar 30 minutos, hasta que esté tibio. Debe quedar húmedo pero sin caldo. Aplasta con el dorso de la cuchara un poco de papa para que la mezcla se pegue.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Papa rellena colombiana: Enfría la mezcla"},{"title":"Forma las bolas","content":"Con las manos húmedas, divide la mezcla en 6 porciones de unos 250 g y aprieta cada una hasta formar una bola compacta de unos 8 cm. Refrigéralas 20 minutos para que se afirmen.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Papa rellena colombiana: Forma las bolas"},{"title":"Prepara el rebozado y sumerge","content":"Mezcla 150 g de harina, 1 huevo, 200 ml de agua fría, ½ cucharadita de sal y ½ cucharadita de azúcar hasta obtener una masa lisa y espesa, como la de las tortas de harina. Sujeta cada bola con un tenedor, sumérgela en el rebozado y deja escurrir el exceso.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Papa rellena colombiana: Prepara el rebozado y sumerge"},{"title":"Fríe las papas","content":"Calienta 1 litro de aceite a 170 °C en una sartén honda. Fríe las papas de 3 en 3, de 6 a 8 minutos, dándoles la vuelta, hasta que estén doradas por todos lados.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Papa rellena colombiana: Fríe las papas"},{"title":"Escurre y sirve","content":"Escúrrelas 2 minutos sobre una rejilla con papel de cocina y sírvelas calientes, con ají colombiano (tomate, cebolla y cilantro picados) y limón.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Papa rellena colombiana: Escurre y sirve"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Papa rellena colombiana"}],"notes":"Para que las bolas no se deshagan al freír, deja enfriar bien la mezcla, apriétalas con firmeza, refrigéralas 20 minutos y usa un rebozado espeso, que cubra sin chorrear. Si el aceite está frío, el rebozado absorbe grasa; si está muy caliente, se dora antes de que el centro se caliente, así que usa un termómetro o prueba con una gota de rebozado, que debe burbujear al instante. El relleno se puede hacer el día anterior y guardar en la nevera; forma las bolas y fríelas el mismo día. Las sobras se conservan 3 días en la nevera; recaliéntalas 15 minutos en horno a 180 °C.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 porción (1 papa rellena, unos 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 6 porciones: 500 g de carne de res cruda (aproximada con datos de falda; se cuenta toda aunque parte de la grasa queda en el caldo), 500 g de papa, 300 g de arroz cocido, 100 g de arvejas, 250 g de tomate, 45 g de cebolla larga, 10 g de cilantro, 150 g de harina, 50 g de huevo, 2 g de azúcar, 6 g de sal y 87 g de aceite de soya (27 g del hogao y 60 g de aceite absorbido en la fritura, una estimación). Se cuenta todo el rebozado aunque parte quede en el bol. No se incluyen el comino ni el ají.","note":"Estimación por porción. La carne y el aceite absorbido varían según el corte y la técnica.","inputs":[{"fdc_id":null,"description":"Beef, brisket, flat half, raw, lean and fat (proxy de la falda o pecho; 500 g crudos; valores aproximados)","grams":500,"per100":{"calories":192,"protein_g":18.7,"carbs_g":0,"fat_g":12.6,"saturated_fat_g":4.95,"fiber_g":0,"sodium_mg":62}},{"fdc_id":"170026","description":"Potatoes, white, flesh and skin, raw (500 g)","grams":500,"per100":{"calories":69,"protein_g":1.68,"carbs_g":15.71,"fat_g":0.1,"saturated_fat_g":0.026,"fiber_g":2.4,"sodium_mg":6}},{"fdc_id":"168878","description":"Rice, white, long-grain, regular, enriched, cooked (300 g de arroz cocido)","grams":300,"per100":{"calories":130,"protein_g":2.69,"carbs_g":28.17,"fat_g":0.28,"saturated_fat_g":0.077,"fiber_g":0.4,"sodium_mg":1}},{"fdc_id":"170419","description":"Peas, green, raw (100 g de arvejas)","grams":100,"per100":{"calories":81,"protein_g":5.42,"carbs_g":14.45,"fat_g":0.4,"saturated_fat_g":0.067,"fiber_g":5.7,"sodium_mg":5}},{"fdc_id":"170457","description":"Tomatoes, red, ripe, raw, year round average (2 tomates ≈ 250 g)","grams":250,"per100":{"calories":18,"protein_g":0.88,"carbs_g":3.92,"fat_g":0.2,"saturated_fat_g":0.028,"fiber_g":1.2,"sodium_mg":5}},{"fdc_id":"170005","description":"Onions, spring or scallions (includes tops and bulb), raw (3 tallos del hogao ≈ 45 g)","grams":45,"per100":{"calories":32,"protein_g":1.83,"carbs_g":7.34,"fat_g":0.19,"saturated_fat_g":0.032,"fiber_g":2.6,"sodium_mg":16}},{"fdc_id":"169997","description":"Coriander (cilantro) leaves, raw (2 cucharadas ≈ 10 g)","grams":10,"per100":{"calories":23,"protein_g":2.13,"carbs_g":3.67,"fat_g":0.52,"saturated_fat_g":0.014,"fiber_g":2.8,"sodium_mg":46}},{"fdc_id":"169761","description":"Wheat flour, white, all-purpose, enriched, bleached (150 g)","grams":150,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.152,"fiber_g":2.7,"sodium_mg":2}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh (1 huevo grande ≈ 50 g)","grams":50,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"169655","description":"Sugars, granulated (½ cucharadita ≈ 2 g)","grams":2,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"172336","description":"Oil, soybean, salad or cooking (27 g del hogao + 60 g de aceite absorbido en la fritura, estimado)","grams":87,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":15.65,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"173468","description":"Salt, table (6 g contados de las 2 cucharaditas, parte de la sal queda en el caldo)","grams":6,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}}]},"seo":{"title":"Papa rellena colombiana de carne desmechada, arroz y arvejas | Manual de Cocina","description":"Papa rellena colombiana: bolas de res desmechada, papa, arroz y arvejas, con rebozado de harina y fritas. Para 6 porciones. Paso a paso con fotos.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"¿Por qué se me deshacen las papas rellenas al freír?","a":"Porque la mezcla estaba caliente o con líquido, o las bolas no estaban bien apretadas. Deja enfriar el guiso, aprieta las bolas, refrigéralas 20 minutos y usa un rebozado espeso."},{"q":"¿Se puede preparar con anticipación?","a":"Sí. El relleno se hace el día anterior y se guarda en la nevera. Forma las bolas, rebózalas y fríelas el mismo día."},{"q":"¿Qué corte de carne se usa?","a":"Falda o pecho de res, que se deshacen bien al cocinarse. También sirve la carne sobrante de un sancocho o de un asado, desmechada."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"fc2e836e-09de-5623-a883-9b95b51b4f91","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"de","slug":"kolumbianische-papa-rellena","public_path":"/de/kolumbianische-papa-rellena","source_url":null,"title":"Kolumbianische Papa rellena","excerpt":"Kolumbianische Papa rellena: Bällchen aus gezupftem Rindfleisch, Kartoffeln, Reis und Erbsen, in Mehlteig getaucht und goldbraun frittiert. 6 Portionen.","summary":"Die kolumbianische Papa rellena, auch Pastel de papa genannt, entsteht aus gezupftem Rindfleisch, Kartoffeln, Reis und Erbsen mit einem Hogao aus Tomate und Frühlingszwiebel, ähnlich der Füllung einer Empanada. Aus der Mischung werden feste Bällchen geformt, in einen Teig aus Mehl und Wasser getaucht und goldbraun frittiert.\n\nSie braucht 30 Minuten Vorbereitung, etwa 2 Stunden 10 Minuten Garzeit und 50 Minuten zum Abkühlen und Ruhen. Ergibt 6 Portionen mit je einer Papa rellena.","category":"Vorspeisen","difficulty":"Mittel","course":"Vorspeise","cuisine":"Kolumbianisch","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["kolumbianische Papa rellena","Papa rellena Rezept","Pastel de papa","gefüllte Kartoffelbällchen","Papa rellena selber machen","Kartoffelbällchen mit Rindfleisch und Reis","kolumbianische Küche"],"ingredients":[{"name":"Rindfleisch (Querrippe oder Brust)","amount":"500","unit":"g","group":"Für das Fleisch"},{"name":"Wasser","amount":"1500","unit":"ml","group":"Für das Fleisch"},{"name":"Knoblauch","amount":"2","unit":"","group":"Für das Fleisch"},{"name":"festkochende Kartoffeln","amount":"500","unit":"g","group":"Für die Füllung"},{"name":"gekochter weißer Reis","amount":"300","unit":"g","group":"Für die Füllung"},{"name":"Erbsen","amount":"100","unit":"g","group":"Für die Füllung"},{"name":"Tomaten","amount":"2","unit":"","group":"Für die Füllung"},{"name":"Frühlingszwiebeln","amount":"5","unit":"","group":"Für die Füllung"},{"name":"Koriandergrün","amount":"2","unit":"Esslöffel","group":"Für die Füllung"},{"name":"Pflanzenöl","amount":"2","unit":"Esslöffel","group":"Für die Füllung"},{"name":"gemahlener Kreuzkümmel","amount":"1/2","unit":"Teelöffel","group":"Für die Füllung"},{"name":"Weizenmehl","amount":"150","unit":"g","group":"Für den Teig"},{"name":"großes Ei","amount":"1","unit":"","group":"Für den Teig"},{"name":"kaltes Wasser","amount":"200","unit":"ml","group":"Für den Teig"},{"name":"Zucker","amount":"1/2","unit":"Teelöffel","group":"Für den Teig"},{"name":"Pflanzenöl zum Frittieren","amount":"1000","unit":"ml","group":"Zum Frittieren und Würzen"},{"name":"Salz","amount":"2","unit":"Teelöffel","group":"Zum Frittieren und Würzen"}],"steps":[{"title":"Fleisch kochen","content":"500 g Rindfleisch mit 1,5 Litern Wasser, 2 Stangen Frühlingszwiebel, 2 Knoblauchzehen und 1 Teelöffel Salz in einen Topf geben. Aufkochen, die Hitze reduzieren, zugedeckt 1 Stunde 30 Minuten garen, bis sich das Fleisch mit der Gabel zerfasern lässt.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Kolumbianische Papa rellena: Fleisch kochen"},{"title":"Fleisch zupfen","content":"Das Fleisch aus der Brühe nehmen, 10 Minuten abkühlen lassen und mit zwei Gabeln in feine Fasern zupfen. 150 ml Brühe aufheben.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Kolumbianische Papa rellena: Fleisch zupfen"},{"title":"Füllung zubereiten","content":"In einer tiefen Pfanne 3 Stangen Frühlingszwiebel und 2 gehackte Tomaten in 2 Esslöffeln Öl mit ½ Teelöffel Salz und ½ Teelöffel Kreuzkümmel 5 Minuten anbraten. 500 g Kartoffeln in 1-cm-Würfeln und die 150 ml Brühe hinzufügen, zugedeckt bei mittlerer bis niedriger Hitze 12 Minuten garen, bis die Kartoffeln weich, aber noch ganz sind. 300 g gekochten Reis, 100 g Erbsen, das Fleisch und 2 Esslöffel gehacktes Koriandergrün dazugeben und 5 Minuten rühren, bis die Flüssigkeit verdampft ist.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Kolumbianische Papa rellena: Füllung zubereiten"},{"title":"Mischung abkühlen lassen","content":"Die Füllung in eine Schüssel geben und 30 Minuten abkühlen lassen, bis sie lauwarm ist. Sie soll feucht, aber ohne Brühe sein. Etwas Kartoffel mit dem Löffelrücken zerdrücken, damit die Mischung zusammenhält.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Kolumbianische Papa rellena: Mischung abkühlen lassen"},{"title":"Bällchen formen","content":"Mit feuchten Händen die Mischung in 6 Portionen zu je etwa 250 g teilen und jede zu einer festen Kugel von etwa 8 cm formen. 20 Minuten kalt stellen, damit sie fest werden.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Kolumbianische Papa rellena: Bällchen formen"},{"title":"Teig anrühren und eintauchen","content":"150 g Mehl, 1 Ei, 200 ml kaltes Wasser, ½ Teelöffel Salz und ½ Teelöffel Zucker zu einem glatten, dicken Teig verrühren, ähnlich einem Pfannkuchenteig. Jede Kugel mit einer Gabel halten, in den Teig tauchen und den Überschuss abtropfen lassen.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Kolumbianische Papa rellena: Teig anrühren und eintauchen"},{"title":"Papas frittieren","content":"1 Liter Öl in einer tiefen Pfanne auf 170 °C erhitzen. Die Papas zu je 3 Stück 6 bis 8 Minuten frittieren und wenden, bis sie rundum goldbraun sind.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Kolumbianische Papa rellena: Papas frittieren"},{"title":"Abtropfen und servieren","content":"2 Minuten auf einem Gitter über Küchenpapier abtropfen lassen und heiß mit kolumbianischer Ají-Sauce (gehackte Tomate, Zwiebel und Koriander) und Limette servieren.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Kolumbianische Papa rellena: Abtropfen und servieren"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Kolumbianische Papa rellena"}],"notes":"Damit die Kugeln beim Frittieren nicht zerfallen, die Mischung gut abkühlen lassen, fest formen, 20 Minuten kalt stellen und einen dicken Teig verwenden, der deckt, ohne abzulaufen. Ist das Öl zu kalt, saugt der Teig Fett auf; ist es zu heiß, bräunt er, bevor die Mitte warm ist. Ein Thermometer nutzen oder einen Tropfen Teig einlegen, der sofort Blasen werfen soll. Die Füllung kann am Vortag zubereitet und kalt gestellt werden; Kugeln formen und am selben Tag frittieren. Reste halten sich 3 Tage im Kühlschrank; 15 Minuten bei 180 °C im Ofen aufwärmen.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 Portion (1 Papa rellena, etwa 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 6 Portionen geteilt: 500 g rohes Rindfleisch (mit Werten für Querrippe angenähert; alles gezählt, obwohl ein Teil des Fetts in der Brühe bleibt), 500 g Kartoffeln, 300 g gekochter Reis, 100 g Erbsen, 250 g Tomate, 45 g Frühlingszwiebel, 10 g Koriandergrün, 150 g Mehl, 50 g Ei, 2 g Zucker, 6 g Salz und 87 g Sojaöl (27 g für die Füllung und 60 g beim Frittieren aufgenommenes Öl, eine Schätzung). Der gesamte Teig wird gezählt, auch wenn ein Teil in der Schüssel bleibt. Kreuzkümmel und Sauce sind nicht enthalten.","note":"Schätzung pro Portion. Fleisch und aufgenommenes Öl schwanken je nach Stück und Technik."},"seo":{"title":"Kolumbianische Papa rellena mit Rindfleisch, Reis und Erbsen | Manual de Cocina","description":"Kolumbianische Papa rellena: Bällchen aus gezupftem Rindfleisch, Kartoffeln, Reis und Erbsen im Teig frittiert. 6 Portionen. Schritt für Schritt mit Fotos.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"Warum zerfallen meine Papas beim Frittieren?","a":"Weil die Mischung noch warm oder zu feucht war oder die Kugeln nicht fest genug geformt wurden. Die Füllung abkühlen lassen, fest drücken, 20 Minuten kalt stellen und einen dicken Teig verwenden."},{"q":"Kann man sie vorbereiten?","a":"Ja. Die Füllung am Vortag zubereiten und kalt stellen. Kugeln formen, in den Teig tauchen und am selben Tag frittieren."},{"q":"Welches Fleisch eignet sich?","a":"Querrippe oder Brust vom Rind, die beim Garen zerfallen. Auch übrig gebliebenes gegartes Rindfleisch lässt sich zupfen und verwenden."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"894892a5-3ae8-59b3-b517-88c42c7fb4d9","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"en","slug":"colombian-papa-rellena","public_path":"/en/colombian-papa-rellena","source_url":null,"title":"Colombian Papa Rellena","excerpt":"Colombian papa rellena: balls of shredded beef, potato, rice and peas, dipped in a flour batter and fried until golden. Serves 6.","summary":"Colombian papa rellena, also called pastel de papa, is made by mixing shredded beef, potato, rice and peas with a tomato and scallion hogao, like an empanada filling. The mixture is shaped into firm balls, dipped in a flour and water batter and fried until golden.\n\nIt takes 30 minutes of prep, about 2 hours 10 minutes of cooking and 50 minutes of cooling and resting. It serves 6, one papa rellena each.","category":"Starters & appetizers","difficulty":"Medium","course":"Starter","cuisine":"Colombian","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["Colombian papa rellena","papa rellena recipe","pastel de papa","stuffed potato balls","how to make papa rellena","beef and rice potato balls","Colombian food"],"ingredients":[{"name":"beef (flank or brisket)","amount":"500","unit":"g","group":"For the beef"},{"name":"water","amount":"1500","unit":"ml","group":"For the beef"},{"name":"garlic","amount":"2","unit":"","group":"For the beef"},{"name":"white potatoes","amount":"500","unit":"g","group":"For the filling"},{"name":"cooked white rice","amount":"300","unit":"g","group":"For the filling"},{"name":"green peas","amount":"100","unit":"g","group":"For the filling"},{"name":"tomatoes","amount":"2","unit":"","group":"For the filling"},{"name":"scallions","amount":"5","unit":"","group":"For the filling"},{"name":"cilantro","amount":"2","unit":"tablespoon","group":"For the filling"},{"name":"vegetable oil","amount":"2","unit":"tablespoon","group":"For the filling"},{"name":"ground cumin","amount":"1/2","unit":"teaspoon","group":"For the filling"},{"name":"all-purpose flour","amount":"150","unit":"g","group":"For the batter"},{"name":"large egg","amount":"1","unit":"","group":"For the batter"},{"name":"cold water","amount":"200","unit":"ml","group":"For the batter"},{"name":"sugar","amount":"1/2","unit":"teaspoon","group":"For the batter"},{"name":"vegetable oil for frying","amount":"1000","unit":"ml","group":"For frying and seasoning"},{"name":"salt","amount":"2","unit":"teaspoon","group":"For frying and seasoning"}],"steps":[{"title":"Cook the beef","content":"Put 500 g beef in a pot with 1.5 liters water, 2 scallions, 2 garlic cloves and 1 teaspoon salt. When it boils, lower the heat, cover and cook for 1 hour 30 minutes, until the beef falls apart with a fork.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Colombian Papa Rellena: Cook the beef"},{"title":"Shred the beef","content":"Take the beef out of the broth, let it cool for 10 minutes and shred it with two forks into fine strands. Save 150 ml of the broth.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Colombian Papa Rellena: Shred the beef"},{"title":"Make the filling","content":"In a deep skillet, sauté 3 chopped scallions and 2 chopped tomatoes in 2 tablespoons oil with ½ teaspoon salt and ½ teaspoon cumin for 5 minutes. Add 500 g potato in 1 cm cubes and the 150 ml broth, cover and cook over medium-low heat for 12 minutes, until the potato is tender but whole. Stir in 300 g cooked rice, 100 g peas, the beef and 2 tablespoons chopped cilantro and mix for 5 minutes, until the liquid has dried up.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Colombian Papa Rellena: Make the filling"},{"title":"Cool the mixture","content":"Transfer the filling to a bowl and let it cool for 30 minutes, until lukewarm. It should be moist but with no broth. Mash a little of the potato with the back of a spoon so the mixture holds together.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Colombian Papa Rellena: Cool the mixture"},{"title":"Shape the balls","content":"With damp hands, divide the mixture into 6 portions of about 250 g and press each into a firm ball about 8 cm across. Chill them for 20 minutes to firm up.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Colombian Papa Rellena: Shape the balls"},{"title":"Make the batter and dip","content":"Whisk 150 g flour, 1 egg, 200 ml cold water, ½ teaspoon salt and ½ teaspoon sugar into a smooth, thick batter, like pancake batter. Hold each ball with a fork, dip it in the batter and let the excess drip off.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Colombian Papa Rellena: Make the batter and dip"},{"title":"Fry the papas","content":"Heat 1 liter of oil to 170 °C in a deep skillet. Fry the papas 3 at a time for 6 to 8 minutes, turning them, until golden all over.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Colombian Papa Rellena: Fry the papas"},{"title":"Drain and serve","content":"Drain them for 2 minutes on a rack lined with paper towels and serve hot with Colombian ají sauce (chopped tomato, onion and cilantro) and lime.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Colombian Papa Rellena: Drain and serve"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Colombian Papa Rellena"}],"notes":"To keep the balls from falling apart while frying, let the mixture cool well, press them firmly, chill them for 20 minutes and use a thick batter that coats without running off. If the oil is too cold, the batter soaks up fat; if it is too hot, it browns before the center is hot, so use a thermometer or drop in a bit of batter, which should sizzle right away. The filling can be made the day before and kept in the fridge; shape and fry the balls the same day. Leftovers keep for 3 days in the fridge; reheat for 15 minutes in a 180 °C oven.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 serving (1 papa rellena, about 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 6 servings: 500 g raw beef (approximated with brisket data; all of it is counted even though some fat stays in the broth), 500 g potato, 300 g cooked rice, 100 g peas, 250 g tomato, 45 g scallions, 10 g cilantro, 150 g flour, 50 g egg, 2 g sugar, 6 g salt and 87 g soybean oil (27 g for the filling and 60 g absorbed while frying, an estimate). All the batter is counted even though some stays in the bowl. Cumin and ají are not included.","note":"Estimate per serving. The beef and the absorbed oil vary by cut and technique."},"seo":{"title":"Colombian Papa Rellena with Shredded Beef, Rice and Peas | Manual de Cocina","description":"Colombian papa rellena: balls of shredded beef, potato, rice and peas, battered and fried until golden. Serves 6. Step by step with photos.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"Why do my papas rellenas fall apart when frying?","a":"Because the mixture was still warm or too wet, or the balls were not pressed firmly. Let the filling cool, press the balls well, chill them for 20 minutes and use a thick batter."},{"q":"Can I make them ahead?","a":"Yes. Make the filling the day before and keep it in the fridge. Shape the balls, batter them and fry them the same day."},{"q":"Which cut of beef should I use?","a":"Flank or brisket, which fall apart as they cook. Leftover cooked beef from a stew or roast, shredded, also works."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"ffe8d577-3db3-56e5-843b-b114f0b2c8ac","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"fr","slug":"papa-rellena-colombienne","public_path":"/fr/papa-rellena-colombienne","source_url":null,"title":"Papa rellena colombienne","excerpt":"Papa rellena colombienne : boules de bœuf effiloché, pommes de terre, riz et petits pois, trempées dans une pâte à la farine et frites jusqu'à dorure. Pour 6 portions.","summary":"La papa rellena colombienne, aussi appelée pastel de papa, se prépare en mélangeant bœuf effiloché, pommes de terre, riz et petits pois avec un hogao de tomate et d'oignon nouveau, comme la farce d'une empanada. On façonne des boules fermes, on les trempe dans une pâte de farine et d'eau et on les fait frire jusqu'à ce qu'elles soient dorées.\n\nElle demande 30 minutes de préparation, environ 2 heures 10 de cuisson et 50 minutes de refroidissement et de repos. Pour 6 portions d'une papa rellena.","category":"Entrées et apéritifs","difficulty":"Moyenne","course":"Entrée","cuisine":"Colombienne","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["papa rellena colombienne","recette papa rellena","pastel de papa","boules de pomme de terre farcies","comment faire une papa rellena","boules de bœuf, riz et pommes de terre","cuisine colombienne"],"ingredients":[{"name":"bœuf (flanchet ou poitrine)","amount":"500","unit":"g","group":"Pour la viande"},{"name":"eau","amount":"1500","unit":"ml","group":"Pour la viande"},{"name":"ail","amount":"2","unit":"","group":"Pour la viande"},{"name":"pommes de terre à chair ferme","amount":"500","unit":"g","group":"Pour la farce"},{"name":"riz blanc cuit","amount":"300","unit":"g","group":"Pour la farce"},{"name":"petits pois","amount":"100","unit":"g","group":"Pour la farce"},{"name":"tomates","amount":"2","unit":"","group":"Pour la farce"},{"name":"oignons nouveaux","amount":"5","unit":"","group":"Pour la farce"},{"name":"coriandre","amount":"2","unit":"cuillère à soupe","group":"Pour la farce"},{"name":"huile végétale","amount":"2","unit":"cuillère à soupe","group":"Pour la farce"},{"name":"cumin moulu","amount":"1/2","unit":"cuillère à café","group":"Pour la farce"},{"name":"farine de blé","amount":"150","unit":"g","group":"Pour la pâte"},{"name":"gros œuf","amount":"1","unit":"","group":"Pour la pâte"},{"name":"eau froide","amount":"200","unit":"ml","group":"Pour la pâte"},{"name":"sucre","amount":"1/2","unit":"cuillère à café","group":"Pour la pâte"},{"name":"huile végétale pour la friture","amount":"1000","unit":"ml","group":"Pour la friture et l'assaisonnement"},{"name":"sel","amount":"2","unit":"cuillère à café","group":"Pour la friture et l'assaisonnement"}],"steps":[{"title":"Cuire la viande","content":"Mettre 500 g de bœuf dans une marmite avec 1,5 litre d'eau, 2 oignons nouveaux, 2 gousses d'ail et 1 cuillère à café de sel. À l'ébullition, baisser le feu, couvrir et cuire 1 heure 30, jusqu'à ce que la viande s'effiloche à la fourchette.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Papa rellena colombienne: Cuire la viande"},{"title":"Effilocher la viande","content":"Sortir la viande du bouillon, la laisser tiédir 10 minutes et l'effilocher avec deux fourchettes en fines fibres. Réserver 150 ml de bouillon.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Papa rellena colombienne: Effilocher la viande"},{"title":"Préparer la farce","content":"Dans une poêle profonde, faire revenir 3 oignons nouveaux et 2 tomates hachés dans 2 cuillères à soupe d'huile avec ½ cuillère à café de sel et ½ cuillère à café de cumin pendant 5 minutes. Ajouter 500 g de pommes de terre en dés de 1 cm et les 150 ml de bouillon, couvrir et cuire à feu moyen-doux 12 minutes, jusqu'à ce que les pommes de terre soient tendres mais entières. Incorporer 300 g de riz cuit, 100 g de petits pois, la viande et 2 cuillères à soupe de coriandre hachée et mélanger 5 minutes, jusqu'à évaporation du liquide.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Papa rellena colombienne: Préparer la farce"},{"title":"Laisser refroidir","content":"Verser la farce dans un saladier et la laisser refroidir 30 minutes, jusqu'à ce qu'elle soit tiède. Elle doit être humide mais sans bouillon. Écraser un peu de pomme de terre avec le dos de la cuillère pour que le mélange se tienne.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Papa rellena colombienne: Laisser refroidir"},{"title":"Former les boules","content":"Avec les mains humides, diviser le mélange en 6 portions d'environ 250 g et presser chacune en une boule ferme d'environ 8 cm. Les réfrigérer 20 minutes pour qu'elles se raffermissent.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Papa rellena colombienne: Former les boules"},{"title":"Préparer la pâte et tremper","content":"Fouetter 150 g de farine, 1 œuf, 200 ml d'eau froide, ½ cuillère à café de sel et ½ cuillère à café de sucre jusqu'à obtenir une pâte lisse et épaisse, comme une pâte à crêpes épaisse. Tenir chaque boule avec une fourchette, la tremper dans la pâte et laisser égoutter l'excédent.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Papa rellena colombienne: Préparer la pâte et tremper"},{"title":"Frire les papas","content":"Chauffer 1 litre d'huile à 170 °C dans une poêle profonde. Faire frire les papas 3 par 3, 6 à 8 minutes, en les retournant, jusqu'à ce qu'elles soient dorées de tous les côtés.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Papa rellena colombienne: Frire les papas"},{"title":"Égoutter et servir","content":"Les égoutter 2 minutes sur une grille garnie de papier absorbant et les servir chaudes avec une sauce ají colombienne (tomate, oignon et coriandre hachés) et du citron vert.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Papa rellena colombienne: Égoutter et servir"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Papa rellena colombienne"}],"notes":"Pour que les boules ne se défassent pas à la friture, bien laisser refroidir le mélange, les presser fermement, les réfrigérer 20 minutes et utiliser une pâte épaisse qui enrobe sans couler. Si l'huile est trop froide, la pâte absorbe la graisse ; si elle est trop chaude, elle dore avant que le centre soit chaud. Utiliser un thermomètre ou plonger une goutte de pâte, qui doit grésiller aussitôt. La farce peut être préparée la veille et gardée au réfrigérateur ; former les boules et les frire le jour même. Les restes se conservent 3 jours au réfrigérateur ; réchauffer 15 minutes au four à 180 °C.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 portion (1 papa rellena, environ 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 6 portions : 500 g de bœuf cru (approché avec des données de poitrine ; tout est compté même si une partie du gras reste dans le bouillon), 500 g de pommes de terre, 300 g de riz cuit, 100 g de petits pois, 250 g de tomate, 45 g d'oignon nouveau, 10 g de coriandre, 150 g de farine, 50 g d'œuf, 2 g de sucre, 6 g de sel et 87 g d'huile de soja (27 g pour la farce et 60 g absorbés à la friture, une estimation). Toute la pâte est comptée, même si une partie reste dans le bol. Le cumin et l'ají ne sont pas inclus.","note":"Estimation par portion. La viande et l'huile absorbée varient selon la pièce et la technique."},"seo":{"title":"Papa rellena colombienne au bœuf effiloché, riz et petits pois | Manual de Cocina","description":"Papa rellena colombienne : boules de bœuf effiloché, pommes de terre, riz et petits pois, frites en pâte. Pour 6 portions. Pas à pas en photos.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"Pourquoi mes papas rellenas se défont-elles à la friture ?","a":"Parce que le mélange était encore chaud ou trop humide, ou que les boules n'étaient pas assez serrées. Laisser refroidir la farce, bien presser les boules, les réfrigérer 20 minutes et utiliser une pâte épaisse."},{"q":"Peut-on les préparer à l'avance ?","a":"Oui. Préparer la farce la veille et la garder au réfrigérateur. Former les boules, les tremper dans la pâte et les frire le jour même."},{"q":"Quelle pièce de bœuf utiliser ?","a":"Du flanchet ou de la poitrine, qui s'effilochent à la cuisson. Un reste de bœuf cuit d'un pot-au-feu ou d'un rôti, effiloché, convient aussi."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"16edc4cf-4b5c-58f8-956b-1c95f9ba0828","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"it","slug":"papa-rellena-colombiana","public_path":"/it/papa-rellena-colombiana","source_url":null,"title":"Papa rellena colombiana","excerpt":"Papa rellena colombiana: palline di manzo sfilacciato, patate, riso e piselli, immerse in una pastella di farina e fritte fino a doratura. Per 6 porzioni.","summary":"La papa rellena colombiana, chiamata anche pastel de papa, si prepara mescolando manzo sfilacciato, patate, riso e piselli con un hogao di pomodoro e cipollotto, come il ripieno di un'empanada. Con il composto si formano palline compatte, che si immergono in una pastella di farina e acqua e si friggono fino a doratura.\n\nRichiede 30 minuti di preparazione, circa 2 ore e 10 di cottura e 50 minuti di raffreddamento e riposo. Per 6 porzioni da una papa rellena.","category":"Antipasti","difficulty":"Media","course":"Antipasto","cuisine":"Colombiana","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["papa rellena colombiana","ricetta papa rellena","pastel de papa","palline di patate ripiene","come fare la papa rellena","palline di manzo, riso e patate","cucina colombiana"],"ingredients":[{"name":"manzo (pancia o petto)","amount":"500","unit":"g","group":"Per la carne"},{"name":"acqua","amount":"1500","unit":"ml","group":"Per la carne"},{"name":"aglio","amount":"2","unit":"","group":"Per la carne"},{"name":"patate a pasta bianca","amount":"500","unit":"g","group":"Per il ripieno"},{"name":"riso bianco cotto","amount":"300","unit":"g","group":"Per il ripieno"},{"name":"piselli","amount":"100","unit":"g","group":"Per il ripieno"},{"name":"pomodori","amount":"2","unit":"","group":"Per il ripieno"},{"name":"cipollotti","amount":"5","unit":"","group":"Per il ripieno"},{"name":"coriandolo","amount":"2","unit":"cucchiaio","group":"Per il ripieno"},{"name":"olio di semi","amount":"2","unit":"cucchiaio","group":"Per il ripieno"},{"name":"cumino macinato","amount":"1/2","unit":"cucchiaino","group":"Per il ripieno"},{"name":"farina 00","amount":"150","unit":"g","group":"Per la pastella"},{"name":"uovo grande","amount":"1","unit":"","group":"Per la pastella"},{"name":"acqua fredda","amount":"200","unit":"ml","group":"Per la pastella"},{"name":"zucchero","amount":"1/2","unit":"cucchiaino","group":"Per la pastella"},{"name":"olio di semi per friggere","amount":"1000","unit":"ml","group":"Per friggere e condire"},{"name":"sale","amount":"2","unit":"cucchiaino","group":"Per friggere e condire"}],"steps":[{"title":"Cuoci la carne","content":"Metti 500 g di manzo in una pentola con 1,5 litri di acqua, 2 cipollotti, 2 spicchi d'aglio e 1 cucchiaino di sale. Quando bolle, abbassa il fuoco, copri e cuoci 1 ora e 30 minuti, finché la carne si sfilaccia con la forchetta.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Papa rellena colombiana: Cuoci la carne"},{"title":"Sfilaccia la carne","content":"Togli la carne dal brodo, lasciala intiepidire 10 minuti e sfilacciala con due forchette in fibre sottili. Conserva 150 ml di brodo.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Papa rellena colombiana: Sfilaccia la carne"},{"title":"Prepara il ripieno","content":"In una padella alta, soffriggi 3 cipollotti e 2 pomodori tritati in 2 cucchiai di olio con ½ cucchiaino di sale e ½ cucchiaino di cumino per 5 minuti. Aggiungi 500 g di patate a dadini di 1 cm e i 150 ml di brodo, copri e cuoci a fuoco medio-basso 12 minuti, finché le patate sono tenere ma intere. Unisci 300 g di riso cotto, 100 g di piselli, la carne e 2 cucchiai di coriandolo tritato e mescola 5 minuti, finché il liquido si asciuga.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Papa rellena colombiana: Prepara il ripieno"},{"title":"Raffredda il composto","content":"Trasferisci il ripieno in una ciotola e lascialo raffreddare 30 minuti, finché è tiepido. Deve essere umido ma senza brodo. Schiaccia un po' di patata con il dorso del cucchiaio perché il composto si leghi.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Papa rellena colombiana: Raffredda il composto"},{"title":"Forma le palline","content":"Con le mani umide, dividi il composto in 6 porzioni da circa 250 g e comprimi ognuna in una palla compatta di circa 8 cm. Mettile in frigorifero 20 minuti perché si rassodino.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Papa rellena colombiana: Forma le palline"},{"title":"Prepara la pastella e immergi","content":"Sbatti 150 g di farina, 1 uovo, 200 ml di acqua fredda, ½ cucchiaino di sale e ½ cucchiaino di zucchero fino a ottenere una pastella liscia e densa, come quella dei pancake. Tieni ogni palla con una forchetta, immergila nella pastella e lascia scolare l'eccesso.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Papa rellena colombiana: Prepara la pastella e immergi"},{"title":"Friggi le papas","content":"Scalda 1 litro di olio a 170 °C in una padella alta. Friggi le papas 3 alla volta per 6-8 minuti, girandole, finché sono dorate da tutti i lati.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Papa rellena colombiana: Friggi le papas"},{"title":"Scola e servi","content":"Scolale 2 minuti su una griglia con carta da cucina e servile calde con salsa ají colombiana (pomodoro, cipolla e coriandolo tritati) e lime.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Papa rellena colombiana: Scola e servi"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Papa rellena colombiana"}],"notes":"Perché le palline non si sfaldino in frittura, lascia raffreddare bene il composto, comprimile con decisione, mettile in frigorifero 20 minuti e usa una pastella densa che copra senza colare. Se l'olio è troppo freddo, la pastella assorbe grasso; se è troppo caldo, si dora prima che il centro si scaldi. Usa un termometro o prova con una goccia di pastella, che deve sfrigolare subito. Il ripieno si può preparare il giorno prima e conservare in frigorifero; forma le palline e friggile lo stesso giorno. Gli avanzi si conservano 3 giorni in frigorifero; riscalda 15 minuti in forno a 180 °C.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 porzione (1 papa rellena, circa 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 6 porzioni: 500 g di manzo crudo (approssimato con dati di petto; si conta tutto anche se parte del grasso resta nel brodo), 500 g di patate, 300 g di riso cotto, 100 g di piselli, 250 g di pomodoro, 45 g di cipollotto, 10 g di coriandolo, 150 g di farina, 50 g di uovo, 2 g di zucchero, 6 g di sale e 87 g di olio di soia (27 g del ripieno e 60 g assorbiti in frittura, una stima). Si conta tutta la pastella, anche se una parte resta nella ciotola. Cumino e ají non sono inclusi.","note":"Stima per porzione. La carne e l'olio assorbito variano secondo il taglio e la tecnica."},"seo":{"title":"Papa rellena colombiana con manzo sfilacciato, riso e piselli | Manual de Cocina","description":"Papa rellena colombiana: palline di manzo sfilacciato, patate, riso e piselli, in pastella e fritte. Per 6 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"Perché le mie papas rellenas si sfaldano in frittura?","a":"Perché il composto era ancora caldo o troppo umido, o le palline non erano compresse a sufficienza. Lascia raffreddare il ripieno, comprimi bene le palline, mettile in frigorifero 20 minuti e usa una pastella densa."},{"q":"Si possono preparare in anticipo?","a":"Sì. Prepara il ripieno il giorno prima e conservalo in frigorifero. Forma le palline, immergile nella pastella e friggile lo stesso giorno."},{"q":"Che taglio di manzo si usa?","a":"Pancia o petto, che si sfilacciano con la cottura. Va bene anche la carne cotta avanzata da un bollito o da un arrosto, sfilacciata."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"18c7bb8a-9a89-52eb-b85e-1beb59178055","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"ja","slug":"コロンビア風パパ・レジェーナ","public_path":"/ja/コロンビア風パパ・レジェーナ","source_url":null,"title":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）","excerpt":"ほぐした牛肉、じゃがいも、ご飯、グリーンピースを丸めて小麦粉の衣をつけ、こんがり揚げたコロンビアの揚げ団子。6人分です。","summary":"コロンビアのパパ・レジェーナ（パステル・デ・パパ）は、ほぐした牛肉、じゃがいも、ご飯、グリーンピースを、トマトと長ねぎのオゴ（ソース）でいため、エンパナーダの具のように仕上げて作ります。その具を固く丸め、小麦粉と水の衣にくぐらせて、こんがりと揚げます。\n\n下ごしらえ30分、加熱約2時間10分、冷ます・休ませる時間が50分です。1人1個で6人分です。","category":"前菜・おつまみ","difficulty":"普通","course":"前菜","cuisine":"コロンビア料理","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["パパ・レジェーナ","コロンビア料理 揚げ物","パステル・デ・パパ","じゃがいも 牛肉 ご飯 揚げ団子","コロンビア 家庭料理","パパレジェーナ 作り方","papa rellena colombiana"],"ingredients":[{"name":"牛肉（バラまたは肩ばら）","amount":"500","unit":"g","group":"肉用"},{"name":"水","amount":"1500","unit":"ml","group":"肉用"},{"name":"にんにく","amount":"2","unit":"","group":"肉用"},{"name":"じゃがいも（男爵など）","amount":"500","unit":"g","group":"具用"},{"name":"炊いた白いご飯","amount":"300","unit":"g","group":"具用"},{"name":"グリーンピース","amount":"100","unit":"g","group":"具用"},{"name":"トマト","amount":"2","unit":"","group":"具用"},{"name":"長ねぎ","amount":"5","unit":"","group":"具用"},{"name":"パクチー","amount":"2","unit":"大さじ","group":"具用"},{"name":"植物油","amount":"2","unit":"大さじ","group":"具用"},{"name":"クミンパウダー","amount":"1/2","unit":"小さじ","group":"具用"},{"name":"薄力粉","amount":"150","unit":"g","group":"衣用"},{"name":"卵（Lサイズ）","amount":"1","unit":"","group":"衣用"},{"name":"冷水","amount":"200","unit":"ml","group":"衣用"},{"name":"砂糖","amount":"1/2","unit":"小さじ","group":"衣用"},{"name":"揚げ油（植物油）","amount":"1000","unit":"ml","group":"揚げ油・味つけ用"},{"name":"塩","amount":"2","unit":"小さじ","group":"揚げ油・味つけ用"}],"steps":[{"title":"牛肉をゆでる","content":"鍋に牛肉500g、水1.5リットル、長ねぎ2本、にんにく2片、塩小さじ1を入れます。沸騰したら弱火にしてふたをし、肉がフォークでほぐれるまで1時間30分ゆでます。","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 牛肉をゆでる"},{"title":"牛肉をほぐす","content":"肉をゆで汁から出して10分冷まし、フォーク2本で細かくほぐします。ゆで汁は150ml取りおきます。","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 牛肉をほぐす"},{"title":"具を炒める","content":"深めのフライパンに油大さじ2を入れ、みじん切りの長ねぎ3本とトマト2個、塩小さじ½、クミン小さじ½を5分炒めます。1cm角に切ったじゃがいも500gとゆで汁150mlを加え、ふたをして中弱火で12分、じゃがいもが形を保ったままやわらかくなるまで煮ます。ご飯300g、グリーンピース100g、牛肉、刻んだパクチー大さじ2を加え、汁けがなくなるまで5分混ぜます。","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 具を炒める"},{"title":"具を冷ます","content":"具をボウルに移し、人肌になるまで30分冷まします。しっとりしていて、汁けがない状態にします。まとまりやすいように、じゃがいもを少しスプーンの背でつぶします。","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 具を冷ます"},{"title":"丸める","content":"手をぬらして、具を約250gずつ6個に分け、それぞれ直径約8cmの固い玉に握ります。固まるように冷蔵庫で20分冷やします。","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 丸める"},{"title":"衣を作ってくぐらせる","content":"小麦粉150g、卵1個、冷水200ml、塩小さじ½、砂糖小さじ½を、パンケーキの生地のようになめらかで濃い衣になるまで混ぜます。玉をフォークで持ち、衣にくぐらせて余分な衣を落とします。","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 衣を作ってくぐらせる"},{"title":"揚げる","content":"深めのフライパンに油1リットルを入れて170°Cに熱します。3個ずつ、ときどき返しながら6〜8分、全体がきつね色になるまで揚げます。","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 揚げる"},{"title":"油をきって盛りつける","content":"網にペーパーを敷いて2分ほど油をきります。熱いうちに、コロンビア風アヒソース（刻んだトマト、玉ねぎ、パクチー）とライムを添えます。","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）: 油をきって盛りつける"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"コロンビア風パパ・レジェーナ（肉入りポテトボール揚げ）"}],"notes":"揚げるときに崩れないように、具をしっかり冷まし、固く握って20分冷やし、たれずに全体を覆う濃い衣を使います。油が冷たいと衣が油を吸い、熱すぎると中が温まる前に焦げます。温度計を使うか、衣を少し落としてすぐに泡立つかを確かめます。具は前日に作って冷蔵庫に入れておけます。玉に丸めて揚げるのは当日にしてください。残りは冷蔵庫で3日間保存でき、180°Cのオーブンで15分温め直します。","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1人分（パパ・レジェーナ1個、約250g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、6人分で割って合計しています。生の牛肉500g（バラ肉のデータで近似、脂の一部はゆで汁に出ますが全量を計算）、じゃがいも500g、ご飯300g、グリーンピース100g、トマト250g、長ねぎ45g、パクチー10g、小麦粉150g、卵50g、砂糖2g、塩6g、大豆油87g（具用27gと、揚げるときに吸収される量の推定60g）を使用しています。衣の一部はボウルに残りますが、全量を計算しています。クミンとアヒソースは含みません。","note":"1人分の目安です。肉の部位や吸収される油の量によって変わります。"},"seo":{"title":"コロンビア風パパ・レジェーナの作り方｜牛肉・ご飯・グリーンピース | Manual de Cocina","description":"ほぐした牛肉、じゃがいも、ご飯、グリーンピースを丸めて衣をつけて揚げるコロンビアのパパ・レジェーナ。6人分。作り方を写真付きで解説します。","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"揚げているときに崩れるのはなぜですか？","a":"具が温かかったり水分が多かったり、握り方がゆるかったりするためです。具をしっかり冷まし、固く握って20分冷やし、濃い衣を使ってください。"},{"q":"前もって準備できますか？","a":"できます。具は前日に作って冷蔵庫に入れておき、玉に丸めて衣をつけて揚げるのは当日にします。"},{"q":"牛肉はどの部位を使いますか？","a":"ゆでるとほぐれやすいバラ肉や肩ばら肉です。煮込みやローストの残りの牛肉をほぐして使うこともできます。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"97395d39-50db-5233-92cf-3ec397f0b876","recipe_group_id":"cddd05c8-39e3-4f69-9ec8-c02d31cb8e6e","language":"pt","slug":"papa-rellena-colombiana","public_path":"/pt/papa-rellena-colombiana","source_url":null,"title":"Papa rellena colombiana (bolinho de carne e batata)","excerpt":"Papa rellena colombiana: bolinhos de carne bovina desfiada, batata, arroz e ervilhas, passados em uma massa de farinha e fritos até dourar. Rende 6 porções.","summary":"A papa rellena colombiana, também chamada de pastel de papa, é feita misturando carne bovina desfiada, batata, arroz e ervilhas com um hogao de tomate e cebolinha, como o recheio de uma empanada. Com a mistura se formam bolas firmes, que são mergulhadas em uma massa de farinha e água e fritas até dourar.\n\nLeva 30 minutos de preparo, cerca de 2 horas e 10 de cozimento e 50 minutos para esfriar e descansar. Rende 6 porções de uma papa rellena.","category":"Entradas e aperitivos","difficulty":"Média","course":"Entrada","cuisine":"Colombiana","prep_time_minutes":30,"cook_time_minutes":130,"total_time_minutes":210,"servings":6,"keywords":["papa rellena colombiana","receita de papa rellena","pastel de papa","bolinho de batata recheado","como fazer papa rellena","bolinho de carne, arroz e batata","comida colombiana"],"ingredients":[{"name":"carne bovina (fraldinha ou peito)","amount":"500","unit":"g","group":"Para a carne"},{"name":"água","amount":"1500","unit":"ml","group":"Para a carne"},{"name":"alho","amount":"2","unit":"","group":"Para a carne"},{"name":"batata","amount":"500","unit":"g","group":"Para o recheio"},{"name":"arroz branco cozido","amount":"300","unit":"g","group":"Para o recheio"},{"name":"ervilhas","amount":"100","unit":"g","group":"Para o recheio"},{"name":"tomates","amount":"2","unit":"","group":"Para o recheio"},{"name":"cebolinha","amount":"5","unit":"","group":"Para o recheio"},{"name":"coentro","amount":"2","unit":"colher de sopa","group":"Para o recheio"},{"name":"óleo vegetal","amount":"2","unit":"colher de sopa","group":"Para o recheio"},{"name":"cominho em pó","amount":"1/2","unit":"colher de chá","group":"Para o recheio"},{"name":"farinha de trigo","amount":"150","unit":"g","group":"Para a massa"},{"name":"ovo grande","amount":"1","unit":"","group":"Para a massa"},{"name":"água gelada","amount":"200","unit":"ml","group":"Para a massa"},{"name":"açúcar","amount":"1/2","unit":"colher de chá","group":"Para a massa"},{"name":"óleo vegetal para fritar","amount":"1000","unit":"ml","group":"Para fritar e temperar"},{"name":"sal","amount":"2","unit":"colher de chá","group":"Para fritar e temperar"}],"steps":[{"title":"Cozinhe a carne","content":"Coloque 500 g de carne bovina em uma panela com 1,5 litro de água, 2 talos de cebolinha, 2 dentes de alho e 1 colher de chá de sal. Quando ferver, baixe o fogo, tampe e cozinhe por 1 hora e 30 minutos, até a carne desfiar com um garfo.","image_url":"/recetas/papa-rellena-colombiana/paso-01.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Cozinhe a carne"},{"title":"Desfie a carne","content":"Retire a carne do caldo, deixe amornar por 10 minutos e desfie com dois garfos em fibras finas. Reserve 150 ml do caldo.","image_url":"/recetas/papa-rellena-colombiana/paso-02.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Desfie a carne"},{"title":"Prepare o recheio","content":"Em uma frigideira funda, refogue 3 talos de cebolinha e 2 tomates picados em 2 colheres de sopa de óleo com ½ colher de chá de sal e ½ colher de chá de cominho por 5 minutos. Junte 500 g de batata em cubos de 1 cm e os 150 ml de caldo, tampe e cozinhe em fogo médio-baixo por 12 minutos, até a batata ficar macia, mas inteira. Acrescente 300 g de arroz cozido, 100 g de ervilhas, a carne e 2 colheres de sopa de coentro picado e mexa por 5 minutos, até o líquido secar.","image_url":"/recetas/papa-rellena-colombiana/paso-03.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Prepare o recheio"},{"title":"Esfrie a mistura","content":"Passe o recheio para uma tigela e deixe esfriar por 30 minutos, até ficar morno. Deve ficar úmido, mas sem caldo. Amasse um pouco da batata com as costas da colher para a mistura grudar.","image_url":"/recetas/papa-rellena-colombiana/paso-04.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Esfrie a mistura"},{"title":"Forme as bolas","content":"Com as mãos úmidas, divida a mistura em 6 porções de cerca de 250 g e aperte cada uma até formar uma bola firme de cerca de 8 cm. Leve à geladeira por 20 minutos para firmarem.","image_url":"/recetas/papa-rellena-colombiana/paso-05.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Forme as bolas"},{"title":"Prepare a massa e mergulhe","content":"Bata 150 g de farinha, 1 ovo, 200 ml de água gelada, ½ colher de chá de sal e ½ colher de chá de açúcar até obter uma massa lisa e grossa, como a de panqueca. Segure cada bola com um garfo, mergulhe na massa e deixe escorrer o excesso.","image_url":"/recetas/papa-rellena-colombiana/paso-06.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Prepare a massa e mergulhe"},{"title":"Frite as papas","content":"Aqueça 1 litro de óleo a 170 °C em uma frigideira funda. Frite as papas de 3 em 3, por 6 a 8 minutos, virando, até dourarem por todos os lados.","image_url":"/recetas/papa-rellena-colombiana/paso-07.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Frite as papas"},{"title":"Escorra e sirva","content":"Escorra por 2 minutos sobre uma grade com papel-toalha e sirva quentes, com molho de ají colombiano (tomate, cebola e coentro picados) e limão.","image_url":"/recetas/papa-rellena-colombiana/paso-08.webp","image_alt":"Papa rellena colombiana (bolinho de carne e batata): Escorra e sirva"}],"image_url":"/recetas/papa-rellena-colombiana/portada.webp","gallery":[{"url":"/recetas/papa-rellena-colombiana/portada.webp","alt":"Papa rellena colombiana (bolinho de carne e batata)"}],"notes":"Para as bolas não se desmancharem na fritura, deixe a mistura esfriar bem, aperte com firmeza, leve à geladeira por 20 minutos e use uma massa grossa, que cubra sem escorrer. Se o óleo estiver frio, a massa absorve gordura; se estiver muito quente, doura antes de o centro esquentar. Use um termômetro ou teste com uma gota de massa, que deve chiar na hora. O recheio pode ser feito no dia anterior e guardado na geladeira; forme as bolas e frite no mesmo dia. As sobras duram 3 dias na geladeira; reaqueça por 15 minutos no forno a 180 °C.","nutrition":{"calories":539,"protein_g":23.4,"carbs_g":51,"fat_g":26.4,"sodium_mg":462,"serving_size":"1 porção (1 papa rellena, cerca de 250 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 6 porções: 500 g de carne bovina crua (aproximada com dados de peito; tudo é contado, mesmo que parte da gordura fique no caldo), 500 g de batata, 300 g de arroz cozido, 100 g de ervilhas, 250 g de tomate, 45 g de cebolinha, 10 g de coentro, 150 g de farinha, 50 g de ovo, 2 g de açúcar, 6 g de sal e 87 g de óleo de soja (27 g do recheio e 60 g absorvidos na fritura, uma estimativa). Toda a massa é contada, mesmo que parte fique na tigela. O cominho e o ají não estão incluídos.","note":"Estimativa por porção. A carne e o óleo absorvido variam conforme o corte e a técnica."},"seo":{"title":"Papa rellena colombiana com carne desfiada, arroz e ervilhas | Manual de Cocina","description":"Papa rellena colombiana: bolinhos de carne bovina desfiada, batata, arroz e ervilhas, empanados em massa e fritos. Rende 6 porções. Passo a passo com fotos.","image_variants":["/recetas/papa-rellena-colombiana/portada-1x1.webp","/recetas/papa-rellena-colombiana/portada-4x3.webp","/recetas/papa-rellena-colombiana/portada-16x9.webp"],"faq":[{"q":"Por que minhas papas rellenas se desmancham na fritura?","a":"Porque a mistura estava quente ou úmida demais, ou as bolas não foram bem apertadas. Deixe o recheio esfriar, aperte bem as bolas, leve à geladeira por 20 minutos e use uma massa grossa."},{"q":"Posso preparar com antecedência?","a":"Pode. Faça o recheio no dia anterior e guarde na geladeira. Forme as bolas, mergulhe na massa e frite no mesmo dia."},{"q":"Que corte de carne devo usar?","a":"Fraldinha ou peito, que desfiam bem ao cozinhar. Sobras de carne cozida de um cozido ou assado, desfiadas, também servem."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/papa-rellena-colombiana') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
